def isEscapePossible(blocked: list[list[int]], source: list[int], target: list[int]) -> bool:
    if not blocked: return True
    blocked_set = set(map(tuple, blocked))
    B = len(blocked)
    limit = B * (B - 1) // 2
    from collections import deque
    def bfs(src, dest):
        q = deque([tuple(src)])
        visited = {tuple(src)}
        while q:
            if len(visited) > limit: return True
            r, c = q.popleft()
            if (r, c) == tuple(dest): return True
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 10**6 and 0 <= nc < 10**6 and (nr, nc) not in blocked_set and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return False
    return bfs(source, target) and bfs(target, source)

